Imports and helpers:
```ts
import type { Locator, Page } from '@playwright/test';

import { expect, test } from './fixtures';
import { ConfigurationPage } from './page-models/configuration-page';

/**
 * Console output Radix emits when `Dialog.Content` has no title/description
 * backing its `aria-labelledby` / `aria-describedby`. Anchored to Radix's own
 * wording rather than to the attribute names, so unrelated app output that
 * mentions `aria-describedby` cannot fail this test.
 */
const dialogAccessibilityWarning =
  /DialogContent. requires a .DialogTitle|Missing .Description. or .aria-describedby/;

/** How long to wait for a console message that is never going to arrive. */
const CONSOLE_SETTLE_MS = 1000;

/** Text of the element a dialog's `aria-labelledby` / `aria-describedby` points at. */
function referredText(
  dialog: Locator,
  attribute: 'aria-labelledby' | 'aria-describedby',
): Promise<string | null> {
  return dialog.evaluate((node, attr) => {
    const id = node.getAttribute(attr);
    return id ? (document.getElementById(id)?.textContent ?? null) : null;
  }, attribute);
}
```

The test body, listener through close:
```ts
  test('Opening the command bar logs no dialog accessibility warnings', async () => {
    // Attach the listener after the budget has loaded so we only capture what
    // the palette open itself produces.
    const messages: string[] = [];
    let settleMatch: () => void = () => {};
    // Resolves on the first Radix dialog warning. `messages` is filled out of
    // band over CDP, so reading it straight after `toBeVisible()` can beat
    // delivery and pass on unfixed code; the race below is the drain.
    const firstDialogWarning = new Promise<void>(resolve => {
      settleMatch = resolve;
    });
    page.on('console', message => {
      if (message.type() !== 'error' && message.type() !== 'warning') return;
      const text = message.text();
      if (!dialogAccessibilityWarning.test(text)) return;
      messages.push(text);
      settleMatch();
    });

    await page.keyboard.press('ControlOrMeta+k');
    await expect(
      page.getByRole('combobox', { name: 'Command Bar' }),
    ).toBeVisible();

    const dialog = page.getByRole('dialog', { name: 'Command Bar' });
    await expect(dialog).toBeAttached();

    // Resolve as soon as a warning lands; on fixed code nothing arrives and the
    // settle timeout is what ends the wait.
    await Promise.race([firstDialogWarning, page.waitForTimeout(CONSOLE_SETTLE_MS)]);

    // Assert the console before the ids below: it is the regression this test
    // exists for, and with the drain above, failing here cannot be a false
    // pass. The id assertions stand on their own as a second line of defence.
    expect(messages).toEqual([]);

    expect(await referredText(dialog, 'aria-labelledby')).toBe('Command Bar');
    // Assert the relationship, not the copy: a locale may translate the
    // description, and the English key only renders as itself because
    // `availableLanguages` is empty under Playwright.
    const description = await referredText(dialog, 'aria-describedby');
    expect(description).toBeTruthy();
    expect(description).not.toBe('Command Bar');

    await page.keyboard.press('Escape');
    await expect(dialog).not.toBeAttached();
  });
```

The two tests below the changed one, `Check the command bar visuals` and `Check the command bar search works correctly`, are untouched.
